WITH with_windows AS (SELECT *, ROUND(humidity / SUM(humidity) OVER (PARTITION BY device_code), 4) AS humidity_share, AVG(status_bits) OVER (PARTITION BY device_code) AS device_code_avg_status_bits, LEAD(humidity, 1) OVER (ORDER BY temp_c, id) AS next_humidity FROM device_readings) SELECT id, device_code, reading_ts, temp_c, humidity, pressure, status_bits, firmware, humidity_share FROM with_windows;
